fn chars_list(s: Str) -> List[Str] {
    var out: List[Str] = []
    for c in s.chars() {
        out = out.push(c)
    }
    return out
}

fn str_at(xs: List[Str], i: Int) -> Str {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return ""
        }
    }
}

fn int_at(xs: List[Int], i: Int) -> Int {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return 0
        }
    }
}

pub fn edit(a: Str, b: Str) -> Int {
    let ca = chars_list(a)
    let cb = chars_list(b)
    let n = ca.len()
    let m = cb.len()

    var prev: List[Int] = []
    var j = 0
    while j <= m {
        prev = prev.push(j)
        j = j + 1
    }

    var i = 1
    while i <= n {
        var cur: List[Int] = [i]
        var jj = 1
        while jj <= m {
            var cost = 1
            if str_at(ca, i - 1) == str_at(cb, jj - 1) {
                cost = 0
            }
            let left = int_at(cur, jj - 1)
            var best = int_at(prev, jj) + 1
            if left + 1 < best {
                best = left + 1
            }
            if int_at(prev, jj - 1) + cost < best {
                best = int_at(prev, jj - 1) + cost
            }
            cur = cur.push(best)
            jj = jj + 1
        }
        prev = cur
        i = i + 1
    }
    return int_at(prev, m)
}
